package com.firecap.app;
import java.io.*;import java.net.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.interfaces.RSAPublicKey;import android.util.Base64;
public final class AdbClient implements Closeable {
 private final Socket socket;private final InputStream in;private final OutputStream out;private final KeyPair key;
 private static final int CNXN=0x4e584e43,AUTH=0x48545541,OPEN=0x4e45504f,OKAY=0x59414b4f,WRTE=0x45545257,CLSE=0x45534c43;
 private static class Msg {int c,a,b;byte[] data;Msg(int c,int a,int b,byte[] d){this.c=c;this.a=a;this.b=b;data=d;}}
 public AdbClient(String host,int port,KeyPair k)throws Exception{key=k;socket=new Socket();socket.connect(new InetSocketAddress(host,port),3000);socket.setSoTimeout(15000);in=socket.getInputStream();out=socket.getOutputStream();send(CNXN,0x01000000,4096,"host::firecap\0".getBytes(StandardCharsets.UTF_8));int attempts=0;while(true){Msg m=read();if(m.c==CNXN)break;if(m.c!=AUTH||m.a!=1)throw new IOException("ADB handshake failed");if(attempts++==0){Signature s=Signature.getInstance("SHA1withRSA");s.initSign(k.getPrivate());s.update(m.data);send(AUTH,2,0,s.sign());}else if(attempts==2)send(AUTH,3,0,pub());else throw new IOException("Approve ADB debugging on Fire TV and retry");}}
 private byte[] pub()throws Exception{RSAPublicKey p=(RSAPublicKey)key.getPublic();java.math.BigInteger n=p.getModulus(),r=java.math.BigInteger.ONE.shiftLeft(32),rr=java.math.BigInteger.ONE.shiftLeft(4096).mod(n),x=n;ByteBuffer b=ByteBuffer.allocate(524).order(ByteOrder.LITTLE_ENDIAN);b.putInt(64);b.putInt(java.math.BigInteger.valueOf(n.intValue()&0xffffffffL).modInverse(r).negate().intValue());for(int i=0;i<64;i++){b.putInt(x.intValue());x=x.shiftRight(32);}for(int i=0;i<64;i++){b.putInt(rr.intValue());rr=rr.shiftRight(32);}b.putInt(p.getPublicExponent().intValue());return (Base64.encodeToString(b.array(),Base64.NO_WRAP)+" firecap@android\0").getBytes(StandardCharsets.UTF_8);}
 private void send(int c,int a,int b,byte[] d)throws IOException{int sum=0;for(byte x:d)sum+=x&255;ByteBuffer h=ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN);h.putInt(c).putInt(a).putInt(b).putInt(d.length).putInt(sum).putInt(c^0xffffffff);out.write(h.array());out.write(d);out.flush();}
 private Msg read()throws IOException{byte[] h=new byte[24];new DataInputStream(in).readFully(h);ByteBuffer b=ByteBuffer.wrap(h).order(ByteOrder.LITTLE_ENDIAN);int c=b.getInt(),a=b.getInt(),v=b.getInt(),len=b.getInt(),sum=b.getInt(),magic=b.getInt();if((c^0xffffffff)!=magic||len<0||len>8000000)throw new IOException("Invalid ADB packet");byte[] d=new byte[len];new DataInputStream(in).readFully(d);int check=0;for(byte x:d)check+=x&255;if(check!=sum)throw new IOException("Corrupt ADB packet");return new Msg(c,a,v,d);}
 public byte[] screenshot()throws Exception{int local=1,remote=0;send(OPEN,local,0,"shell:screencap -p\0".getBytes(StandardCharsets.UTF_8));ByteArrayOutputStream result=new ByteArrayOutputStream();while(true){Msg m=read();if(m.c==OKAY)remote=m.a;else if(m.c==WRTE){remote=m.a;result.write(m.data);send(OKAY,local,remote,new byte[0]);if(result.size()>30000000)throw new IOException("Screenshot too large");}else if(m.c==CLSE){send(CLSE,local,m.a,new byte[0]);break;}else throw new IOException("ADB capture failed");}byte[] d=result.toByteArray();if(d.length<8||d[0]!=(byte)137||d[1]!=80)throw new IOException("No screenshot available");return d;}
 public void close()throws IOException{socket.close();}
 public static KeyPair newKey()throws Exception{KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);return g.generateKeyPair();}
}